<div class="right_col" role="main"><h2 class="mb-3">Create Lottery</h2><div class="card shadow-sm"><div class="card-body"><?= form_open('school/admission/lotteries/save') ?><div class="row"><div class="col-md-6 mb-3"><label>School *</label><select id="admission-school" class="form-control" name="school_id"><?php foreach($schools as $s): ?><option value="<?= $s->id ?>"><?= esc($s->name) ?></option><?php endforeach ?></select></div><div class="col-md-6 mb-3"><label>Lottery circular *</label><select id="lottery-circular" class="form-control" name="circular_id"><?php foreach($circularItems as $c): ?><option value="<?= $c->id ?>"><?= esc($c->title) ?></option><?php endforeach ?></select></div><div class="col-12 mb-3"><label>Lottery name *</label><input class="form-control" name="name" value="<?= esc(old('name')) ?>" required></div><div class="col-md-6 mb-3"><label>Selected seats *</label><input type="number" min="1" class="form-control" name="seat_count" required></div><div class="col-md-6 mb-3"><label>Waiting-list places *</label><input type="number" min="0" class="form-control" name="waiting_count" value="0" required></div></div><button class="btn btn-primary">Create lottery</button></form></div></div></div><script>document.getElementById('admission-school').addEventListener('change',async function(){const d=await fetch('<?= base_url('school/admission/academic-data') ?>/'+this.value).then(r=>r.json());document.getElementById('lottery-circular').innerHTML=d.circulars.map(x=>`<option value="${x.id}">${x.title}</option>`).join('');});</script>
